+    }
+
+    @Override
+    public void writeTo(StreamOutput out) throws IOException {
+        out.writeDoubleArray(expectations);
+        out.writeBoolean(fractions != null);
+        if (fractions != null) {
+            out.writeDoubleArray(fractions);
+        }
+        out.writeVLong(docCount);
+    }
