+                .put(settings.filter(k -> {
+                    if (UNREMOVABLE_SETTINGS.contains(k) == false) {
+                        for (String filterKey : keyFilters) {
+                            if (k.equals(filterKey)) {
+                                return false;
+                            }
+                        }
